-- Institutional records extracted from the `institutes` table in the supplied SQL dump.
-- Source columns mapped: grid -> grid_id; name -> name; slug generated from name.
-- Source seq_no and pub_count are not inserted because the current institutions schema has no matching columns.
-- Nullable fields and fields with defaults are left to the target table.
-- Safe to re-run: duplicate slugs update grid_id and name without overwriting other institution metadata.

START TRANSACTION;

ON DUPLICATE KEY UPDATE
  `grid_id` = VALUES(`grid_id`),
  `name` = VALUES(`name`);

COMMIT;
